public class METTestSalesOrderDualWriteUpdate extends RunBaseBatch
{
    SalesId      salesId;
    Integer      LinesToUpdate;
    Integer      UpdateType;
    Integer      TransactionSize;
    boolean      isSkipBusinessEvents;

    DialogField  dlgSalesId;
    DialogField  dlgLinesToUpdate;
    DialogField  dlgUpdateType;
    DialogField  dlgTransactionSize;
    DialogField  dlgIsSkipBusinessEvents;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        salesId,
        LinesToUpdate,
        UpdateType,
        TransactionSize,
        isSkipBusinessEvents
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgSalesId        = dialog.addFieldValue(extendedtypestr(SalesId), salesId);
    dlgSalesId.mandatory_RU(true);
    dlgLinesToUpdate  = dialog.addFieldValue(extendedtypestr(Integer), LinesToUpdate, "LinesToUpdate", "Help text");
    dlgUpdateType     = dialog.addFieldValue(extendedtypestr(Integer), UpdateType, "Update type (check METTestSalesOrderDualWriteUpdate for options)", "Help text");
    dlgTransactionSize = dialog.addFieldValue(extendedtypestr(Integer), TransactionSize, "TransactionSize", "Help text");
    dlgIsSkipBusinessEvents = dialog.addFieldValue(extendedTypeStr(NoYesId), isSkipBusinessEvents, "SkipBusinessEvents", "Help text");

    return dialog;
}

public boolean getFromDialog()
{
    ;
    salesId              = dlgSalesId.value();
    LinesToUpdate        = dlgLinesToUpdate.value();
    UpdateType           = dlgUpdateType.value();
    TransactionSize      = dlgTransactionSize.value();
    isSkipBusinessEvents = dlgIsSkipBusinessEvents.value();

    return super();
}

public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

public Integer parmLinesToUpdate(Integer _LinesToUpdate = LinesToUpdate)
{
    LinesToUpdate = _LinesToUpdate;
    return LinesToUpdate;
}

public Integer parmUpdateType(Integer _UpdateType = UpdateType)
{
    UpdateType = _UpdateType;
    return UpdateType;
}

public Integer parmTransactionSize(Integer _TransactionSize = TransactionSize)
{
    TransactionSize = _TransactionSize;
    return TransactionSize;
}

public boolean parmIsSkipBusinessEvents(boolean _isSkipBusinessEvents = isSkipBusinessEvents)
{
    isSkipBusinessEvents = _isSkipBusinessEvents;
    return isSkipBusinessEvents;
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = _packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public void run()
{
    if (! this.validate())
    {
        throw error("Validation error");
    }

    SalesLine    salesLine, salesLineUpdate;
    int starttime = timeNow();
    int i;

    ttsbegin;

    while select salesLine
            where salesLine.SalesId == salesId
    {
        salesLineUpdate = SalesLine::findRecId(salesLine.RecId, true);

        if (UpdateType == 2)
        {
            this.triggerDualWrite(salesId, salesLineUpdate.LineCreationSequenceNumber);
        }
        else if (UpdateType == 3)
        {
            this.triggerDualWriteV2(salesId, salesLineUpdate.LineCreationSequenceNumber);
        }
        else
        {
            if (isSkipBusinessEvents)
            {
                salesLineUpdate.skipBusinessEvents(true);
            }

            if (UpdateType == 0)
            {
                if (salesLineUpdate.SalesStatus != SalesStatus::Canceled)
                {
                    salesLineUpdate.SalesStatus = SalesStatus::Canceled;
                }
                else
                {
                    salesLineUpdate.SalesStatus = SalesStatus::Backorder;
                }

                salesLineUpdate.SalesQty++;
            }

            if (UpdateType == 1)
            {
                salesLineUpdate.CostPrice += 1;
            }

            salesLineUpdate.doUpdate();
        }

        i++;

        if (i >= LinesToUpdate)
        {
            break;
        }

        if (TransactionSize > 0 && i mod TransactionSize == 0)
        {
            ttscommit;
            ttsbegin;
        }
    }

    ttscommit;

    info(strFmt('SalesId: %1 - LinesToUpdate: %2 - UpdateType: %3 - TransactionSize: %4 - SkipBusinessEvents: %5 - Processed: %6 - Time: %7',
        salesId, LinesToUpdate, UpdateType, TransactionSize, isSkipBusinessEvents, i, timenow() - starttime));
}

public void triggerDualWrite(SalesId _salesId, SalesLineCreationSequenceNumber _lineCreationSequenceNumber)
{
    TableId entityTableId = tableName2Id('SalesOrderLineCDSV2Entity');

    // Get entity RecId for the record you want to sync
    SalesOrderLineCDSV2Entity entityRec;

    select firstonly RecId from entityRec
        where entityRec.SalesOrderNumber == _salesId
        && entityRec.LineCreationSequenceNumber == _lineCreationSequenceNumber;

    if (entityRec.RecId)
    {
        DictClass dictClass = new DictClass(className2Id('DualWriteTransactionCacheManager'));
        Object cacheManager = dictClass.makeObject();
        dictClass.callObject('addToCache', cacheManager, entityTableId, entityRec.RecId);
    }
}

public void triggerDualWriteV2(SalesId _salesId, SalesLineCreationSequenceNumber _lineCreationSequenceNumber)
{
    SalesOrderLineCDSV2Entity entityRec;

    select firstonly entityRec
      where entityRec.SalesOrderNumber          == _salesId
         && entityRec.LineCreationSequenceNumber == _lineCreationSequenceNumber;

    if (!entityRec.RecId)
    {
        return;
    }

    DictClass autoPauseClass    = new DictClass(className2Id('DualWriteAutoPause'));
    Object    autoPause         = autoPauseClass.callStatic('CreateOutbound');

    DictClass syncOutboundClass = new DictClass(className2Id('DualWriteSyncOutbound'));
    Object    syncOutbound      = syncOutboundClass.callStatic('construct', autoPause);

    syncOutboundClass.callObject('ForceSyncToCDS', syncOutbound, entityRec, true);
}

public static METTestSalesOrderDualWriteUpdate construct()
{
    return new METTestSalesOrderDualWriteUpdate();
}

static ClassDescription description()
{
    return "Test dual write update of Sales order";
}

public static void main(Args _args)
{
    METTestSalesOrderDualWriteUpdate    runObject = METTestSalesOrderDualWriteUpdate::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
